import type { BodyView, MuscleId } from '../../domain/muscles';
import art from './bodyArt.json';

/**
 * Body map figure, generated by `scripts/body-art` (see its README). Derived from "Muscles front
 * and back.svg" by OpenStax, Tomáš Kebert and umimeto.org, CC BY-SA 4.0: an original,
 * exaggerated physique with ink outlines. Coordinates are absolute (no transforms, no mirroring).
 */
export type ArtKind = 'body' | 'tendon' | 'line' | 'muscle';

export interface ArtPart {
  k: ArtKind;
  d: string;
  /** Muscle drawn by this shape (k === 'muscle'). */
  m?: MuscleId;
  /** Clip path (absolute coordinates): splits one drawn deltoid into its heads. */
  clip?: string;
  /** Hairline shapes: no heavy outline. */
  thin?: boolean;
  /** Head shapes: filled, never inked (a plain silhouette). */
  noInk?: boolean;
}

export interface BodyArt {
  viewBox: string;
  /** Paint order: later parts are drawn on top. */
  parts: readonly ArtPart[];
  /** Fine lines between deltoid heads, each clipped to its deltoid shape. */
  seams: readonly { d: string; clip: string }[];
}

export const BODY_ART = art as unknown as Readonly<Record<BodyView, BodyArt>>;

/**
 * Approximate surface of a path: shoelace formula over its points (Bézier control points included).
 * Good enough to rank shapes by size, which bounding boxes are not for thin crescents.
 */
export function approxArea(d: string): number {
  const n = (d.match(/-?\d+(\.\d+)?/g) ?? []).map(Number);
  let twice = 0;
  for (let i = 0; i + 1 < n.length; i += 2) {
    const x1 = n[i] ?? 0;
    const y1 = n[i + 1] ?? 0;
    const x2 = n[(i + 2) % n.length] ?? 0;
    const y2 = n[(i + 3) % n.length] ?? 0;
    twice += x1 * y2 - x2 * y1;
  }
  return Math.abs(twice) / 2;
}
